[data-workspace-area="conversation"]{background-image:var(--sx-actor),radial-gradient(120% 55% at 50% -12%,color-mix(in srgb,var(--sx-accent) var(--sx-ambient),transparent),transparent 62%)!important;background-size:160px 84px,100% 100%!important;background-position:right 56px top 20px,0 0!important;background-repeat:no-repeat,no-repeat!important}
[data-workspace-area="conversation"]::before{background:linear-gradient(var(--sx-dot) 1px,transparent 1px) 0 0/100% 4px,linear-gradient(90deg,var(--sx-dot) 1px,transparent 1px) 0 0/4px 100%;-webkit-mask:linear-gradient(#000 20%,transparent 90%);mask:linear-gradient(#000 20%,transparent 90%)}
[data-workspace-area="conversation"]::after{background:radial-gradient(70% 55% at 50% 0%,color-mix(in srgb,var(--sx-accent) 10%,transparent),transparent 72%);opacity:0}
:root:has(.chat-markdown[data-streaming],.live-tool-shine) [data-workspace-area="conversation"]::after{opacity:1}
[data-slot="sidebar-inner"]{background-image:var(--sx-side-glow),var(--surface-grain,none)!important;background-size:100% 100%,var(--surface-grain-size,auto)!important;background-position:0 0,0 0!important;background-repeat:no-repeat,repeat!important}
